import sys  # system functions
import random  # random number generation
from time import perf_counter  # timing

defect = 0  # defect action
cooperate = 1  # cooperate action

payoffMatrix = [  # payoff matrix
    [3, 0],
    [5, 1],   
]

def parse_cli(argv):
    if len(argv) < 3:
        print("Usage: python3 Alter_J_assignment3.py grid_size steps num_processes")
        sys.exit(1)
    size  = int(argv[1])
    steps = int(argv[2])
    # num_processes accepted to satisfy spec, but unused in this sequential file
    nprocs = int(argv[3]) if len(argv) >= 4 else 1
    return size, steps, nprocs

# Grid Helpers and Initialization
def makeShape(size, value):
    return [[value for _ in range(size)] for _ in range(size)]

def initializeActionGrid0(size, grid):
    # Random init (NOT used for grading; but im keeping it in)
    for i in range(size):
        for j in range(size):
            grid[i][j] = cooperate if (random.random() < 0.5) else defect

def initializeActionGrid1(size, grid):
    # Top half cooperate, bottom half defect.
    for i in range(size):
        for j in range(size):
            grid[i][j] = cooperate if i < size/2 else defect

def initializeActionGrid2(size, grid):
    # All cooperate except the main diagonal which defects.
    for i in range(size):
        for j in range(size):
            grid[i][j] = defect if i == j else cooperate

def initializeActionGrid3(size, grid):
    # All cooperate except the center cell which defects.
    for i in range(size):
        for j in range(size):
            grid[i][j] = cooperate
    grid[size // 2][size // 2] = defect

def initializeActionGrid4(size, grid):
    # All cooperate except (1,1) which defects (or (0,0) if size==1
    for i in range(size):
        for j in range(size):
            grid[i][j] = cooperate
    if size > 1:
        grid[1][1] = defect
    else:
        grid[0][0] = defect

def getNeighbors(i, j, size):
    # Updated/correct neighbor function: 4-neighborhood (N,S,E,W), no wrap.
    neighbors = []
    if i > 0:            neighbors.append((i-1, j))
    if i + 1 < size:     neighbors.append((i+1, j))
    if j + 1 < size:     neighbors.append((i, j+1))
    if j > 0:            neighbors.append((i, j-1))
    return neighbors

# Reward Computation
def computeReward(i, j, actionGrid, gridSize):
    # Sum PD payoff against N,S,E,W neighbors.
    myAction = actionGrid[i][j]
    total = 0
    for ni, nj in getNeighbors(i, j, gridSize):
        total += payoffMatrix[myAction][actionGrid[ni][nj]]
    return total

# Sequential simulation of the grid game

def run_simulation_seq(initF, size, steps, out_name):
    actionGrid = makeShape(size, cooperate)
    rewardGrid = makeShape(size, 0)
    workGrid   = makeShape(size, cooperate)

# Determinsitc init 
    initF(size, actionGrid)
    print(f"{initF.__name__}, size={size}, steps={steps}, fName={out_name}")

    for ss in range(steps):
        # (1) compute rewardGrid from current actionGrid
        for i in range(size):
            for j in range(size):
                rewardGrid[i][j] = computeReward(i, j, actionGrid, size)

        # (2) decide new action by striclty greater reward among {self + neighbors}
        for i in range(size):
            for j in range(size):
                 bestReward = rewardGrid[i][j]
                 newAction = actionGrid[i][j]
                 for ii, jj in getNeighbors(i, j, size):
                    if rewardGrid[ii][jj] > bestReward:  # STRICT >
                        bestReward = rewardGrid[ii][jj]
                        newAction  = actionGrid[ii][jj]
                 workGrid[i][j] = newAction

        # (3) commit workGrid to actionGrid
        for i in range(size):
            for j in range(size):
                actionGrid[i][j] = workGrid[i][j]
        
        # screen counts (should match the reference output)
        coopCount = sum(1 for i in range(size) for j in range(size) if actionGrid[i][j] == cooperate)
        defCount  = size*size - coopCount
        print(f"step {ss}: {coopCount} cooperates, {defCount} defects")

    with open(out_name, "w") as f:
        for i in range(size):
            f.write(f"{i}: {actionGrid[i]}\n")    
    
def run_all(size, steps, nprocs):
    # DO NOT include initializeActionGrid0 (random) in grading runs
    jobs = [
        (initializeActionGrid1, f"output_grid1_{size}_{steps}_seq.txt"),
        (initializeActionGrid2, f"output_grid2_{size}_{steps}_seq.txt"),
        (initializeActionGrid3, f"output_grid3_{size}_{steps}_seq.txt"),
        (initializeActionGrid4, f"output_grid4_{size}_{steps}_seq.txt"),
    ]
    t0 = perf_counter()
    for initF, out_name in jobs:
        run_simulation_seq(initF, size, steps, out_name)
    t1 = perf_counter()
    # Keep this timing line for your report; nprocs is accepted but unused here
    print(f"Total time (all 4 sims): {t1 - t0:.3f} sec with nprocs={nprocs}")    
            
if __name__ == "__main__":
    size, steps, nprocs = parse_cli(sys.argv)
    run_all(size, steps, nprocs)




    










    




